import csv
import re
from decimal import Decimal


_FIELDS = {'id', 'team', 'amount', 'status'}
_STATUSES = {'settled', 'pending', 'cancelled'}
_AMOUNT = re.compile(r'-?[0-9]+(?:\.[0-9]{1,2})?')


def read_rows(lines):
    reader = csv.reader(lines, strict=True)
    rows = []
    seen = set()
    try:
        header = next(reader, None)
        if header is None or len(header) != 4 or set(header) != _FIELDS:
            raise ValueError('header must contain exactly id, team, amount, status')
        for fields in reader:
            if len(fields) != 4:
                raise ValueError('each row must contain exactly four fields')
            row = dict(zip(header, (value.strip() for value in fields)))
            if not row['id'] or not row['team']:
                raise ValueError('id and team must be nonempty')
            if row['id'] in seen:
                raise ValueError('duplicate id: ' + row['id'])
            if row['status'] not in _STATUSES:
                raise ValueError('invalid status: ' + row['status'])
            if _AMOUNT.fullmatch(row['amount']) is None:
                raise ValueError('invalid amount: ' + row['amount'])
            row['amount'] = Decimal(row['amount'])
            seen.add(row['id'])
            rows.append(row)
    except csv.Error as exc:
        raise ValueError('invalid CSV: ' + str(exc)) from exc
    return rows

