from decimal import Decimal


def summarize(rows):
    totals = {}
    for row in rows:
        if row['status'] != 'settled':
            continue
        # Parsed amounts have at most two fractional digits. Integer cents
        # avoid rounding imposed by the caller's Decimal context.
        sign, digits, exponent = row['amount'].as_tuple()
        cents = 0
        for digit in digits:
            cents = cents * 10 + digit
        cents *= 10 ** (exponent + 2)
        if sign:
            cents = -cents
        team = row['team']
        totals[team] = totals.get(team, 0) + cents
    return {
        team: format(Decimal((int(cents < 0), Decimal(abs(cents)).as_tuple().digits, -2)), 'f')
        for team, cents in totals.items()
    }

